pm.test("沒給交易模式，卻照這一份記著的現貨走：每一筆都是做多", function () {
    pm.response.json().closedTrades.forEach(function (trade) {
        pm.expect(trade.direction).to.eql("long");
    });
});

pm.test("部位規劃也改到了，而且拿掉的那一格真的不在了", function () {
    const plan = pm.response.json().positionPlan;
    pm.expect(plan.capital).to.eql("80000");
    // 整份改寫就是整份：留白的停利距離要歸零，不是沿用上一版。
    pm.expect(plan.takeProfitPercentage).to.eql("0");
});

