{
  "name": "布林通道 {{$timestamp}}",
  "resultType": "floatList",
  "script": "package main

import "indicator"

func Calculate(data []indicator.KCandle) map[string][]float64 {
	period := indicator.LookbackCount("期數")
	_ = indicator.Number("倍數")
	middle := []float64{}
	for i := period - 1; i < len(data); i++ {
		sum := 0.0
		for _, candle := range data[i-period+1 : i+1] {
			sum += candle.Close
		}
		middle = append(middle, sum/float64(period))
	}
	return map[string][]float64{"中線": middle}
}
",
  "parameters": [
    { "name": "期數", "kind": "lookbackCount", "defaultValue": 20 },
    { "name": "倍數", "kind": "number", "defaultValue": 2 }
  ]
}

